import {routes,sectionFor,chatPayload,sampleText,messageForAnswer} from './journey.mjs?v=20260917-2';
import {discover,getStatus,getCode,setCode,mode,setMode,api,fileData} from './live-client.mjs?v=20260917-2';
import {seed,stats,comparison,brief,dailySeries,parseDemo,addObservation,editObservation,removeObservation} from './model.mjs?v=20260917-2';
const KEY='stillwell-demo-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=seed();}catch{state=seed();}
let ux;try{ux=JSON.parse(localStorage.getItem('stillwell-ux-v1'))||{};}catch{ux={};}
function saveUx(){localStorage.setItem('stillwell-ux-v1',JSON.stringify(ux));}
let selectedRecord=null,chatError=null,extractionAttempt=0,retryFile=null,focusEntry=null;
let aiBusy=false,liveExtraction=null;const originalFiles=new Map();
let route=location.hash.slice(1)||'overview',filter='',activeTab='All records',compare='Sleep',draft='',familyPreview=false;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z',records:'M6 3h9l4 4v14H6Z M14 3v5h5 M9 12h7 M9 16h7',track:'M3 12h4l3-8 4 16 3-8h4',insights:'M4 20V9 M11 20V4 M18 20v-8',visit:'M4 5h16v16H4Z M8 2v6 M16 2v6 M4 10h16',family:'M16 21v-2a5 5 0 0 0-10 0v2 M11 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 5a4 4 0 0 1 0 8 M20 21v-3a4 4 0 0 0-2-3',arrow:'m9 5 7 7-7 7',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',check:'m5 12 4 4 10-10',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',close:'m6 6 12 12 M18 6 6 18',clock:'M12 8v5l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',leaf:'M5 19C-2 5 12 2 21 3c1 10-4 19-16 16Zm0 0L16 8',edit:'m4 16 12-12 4 4L8 20H4Z',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z',mail:'M3 5h18v14H3Z m0 0 9 8 9-8',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};
const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.records}"/></svg>`;
const nav=[['overview','home','Overview'],['companion','chat','Companion'],['records','records','Health records'],['tracking','track','Daily journal'],['insights','insights','Patterns & insights'],['visits','visit','Appointments'],['family','family','Family circle']];
function save(){localStorage.setItem(KEY,JSON.stringify(state));}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function date(d){if(!d)return 'Date not supplied';return new Date(d+'T12:00:00').toLocaleDateString('en-SG',{day:'numeric',month:'short'});}
function button(label,action,style='secondary',i=''){return `<button class="btn ${style}" data-action="${action}">${i?icon(i):''}${label}</button>`;}
function go(r){route=routes.includes(r)?r:'overview';ux.lastRoute=route;saveUx();location.hash=route;window.scrollTo(0,0);render();if(!focusEntry||route!=='tracking')$('.page-heading h1')?.focus({preventScroll:true});}
function header(title,sub,actions=''){return `<div class="page-heading"><div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function miniTag(text,type=''){return `<span class="tag ${type}">${text}</span>`;}
function chart(full=false){
 let days=dailySeries(state),segments=[];
 for(let o of days.filter(o=>Number.isFinite(o.severity))){let p={x:44+(+o.date.slice(-2)-1)*43,y:150-o.severity*23,o};let last=segments.at(-1)?.at(-1);if(!last||(+o.date.slice(-2)-+last.o.date.slice(-2))>1)segments.push([]);segments.at(-1).push(p);}
 return `<svg class="trend-chart" viewBox="0 0 650 205" role="img" aria-label="Daily average headache severity with gaps for unlogged days${full?', and reported sleep on a separate hours axis':''}"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c88878" stop-opacity=".4"/><stop offset="1" stop-color="#c88878" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3,4,5].map(v=>`<line x1="35" x2="590" y1="${150-v*23}" y2="${150-v*23}" stroke="#e8e3de" stroke-dasharray="3 5"/><text x="15" y="${154-v*23}" class="svg-label">${v}</text>`).join('')}${full?days.filter(o=>Number.isFinite(o.sleep)).map(o=>`<rect x="${38+(+o.date.slice(-2)-1)*43}" y="${150-o.sleep*12}" height="${o.sleep*12}" width="13" fill="#d7b570" opacity=".65" rx="4"><title>${date(o.date)}: ${o.sleep.toFixed(1)} hours sleep</title></rect>`).join(''):''}${segments.map(points=>{let path=points.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' ');return `<path d="${path} L${points.at(-1).x},155 L${points[0].x},155Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#9a493d" stroke-width="2.5"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="white" stroke="#9a493d" stroke-width="2"><title>${date(p.o.date)}: ${p.o.severity.toFixed(1)}/5 daily mean</title></circle>`).join('')}`;}).join('')}${full?[0,4,8,10].map(v=>`<text x="611" y="${154-v*12}" class="svg-label">${v}h</text>`).join(''):''}${[1,3,5,7,9,11,13].map(d=>`<text x="${44+(d-1)*43}" y="183" text-anchor="middle" class="svg-label">${d} Sep</text>`).join('')}<text x="620" y="202" text-anchor="end" class="svg-label">Daily means • gaps are unlogged days • synthetic journal</text></svg>`;
}
function journalRows(limit=Infinity,editable=true){return state.observations.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,limit).map(o=>`<div class="journal-row ${focusEntry===o.id?'entry-highlight':''}" id="entry-${o.id}" tabindex="-1"><div class="date-block">${date(o.date)}</div><div class="journal-main"><strong>${esc(o.symptom)}</strong><p>${esc(o.note)}</p><span class="quiet">${esc(o.source)} ${Number.isFinite(o.sleep)?` · ${o.sleep}h sleep`:''}</span></div><span class="severity sev-${o.severity??0}">${o.severity??'—'}<small>/5</small></span>${editable?`<button class="icon-btn" data-edit="${o.id}" aria-label="Edit ${esc(o.symptom)} on ${date(o.date)}">${icon('edit')}</button>`:''}</div>`).join('');}
function overview(){const last=ux.lastSaved,valid=last&&(last.kind==='observation'?state.observations:state.records).some(x=>x.id===last.id);return `${header('How can we help today?','Maya’s fictional profile · Demo timeline: 1–13 September 2026')}${!ux.introDismissed?`<section class="intro-note"><div><strong>A little clarity, one step at a time.</strong><p>Talk about how you feel, understand your records and prepare questions for your next appointment. Explore in any order.</p></div>${button('Got it','dismiss-intro')}</section>`:''}<section class="welcome today-welcome"><div class="welcome-copy"><span class="greeting">Your everyday companion</span><h2>How are you<br>feeling today?</h2><p>Talk it through. If there’s something to record, you’ll review it before it goes into your journal.</p>${button('Talk about how I’m feeling','talk','primary','chat')}</div><div class="today-aside"><div class="today-context-label">Your story so far</div><button class="context-stat" data-route="tracking"><span class="stat-icon">${icon('track')}</span><strong>${new Set(state.observations.map(o=>o.date)).size}<small>days recorded</small></strong>${icon('arrow')}</button><button class="context-stat" data-route="visits"><span class="stat-icon">${icon('visit')}</span><strong>${state.questions.length}<small>questions for your visit</small></strong>${icon('arrow')}</button><p>From your demonstration profile.</p></div></section><div class="journey-options"><button class="journey-option" data-action="upload">${icon('records')}<span><strong>Understand a health report</strong><small>Bring a document, check the details and ask about it. A sample is ready to try.</small></span>${icon('arrow')}</button><button class="journey-option" data-route="visits">${icon('visit')}<span><strong>Prepare for an appointment</strong><small>Gather your concerns and useful history into a brief you can bring along.</small></span>${icon('arrow')}</button></div>${valid?`<section class="saved-receipt"><div><strong>Pick up where you left off</strong><p>${esc(last.label)}</p></div><button class="btn secondary" ${last.kind==='observation'?`data-view-entry="${last.id}"`:`data-record="${last.id}"`}>View saved ${last.kind==='observation'?'entry':'record'} →</button></section>`:''}<section class="panel today-history"><div class="panel-heading"><div><h3>Your recent days</h3><p>${stats(state).entries} journal entries · Unlogged days stay unknown</p></div><button class="text-btn" data-route="tracking">Open journal →</button></div>${journalRows(2)}<button class="text-btn" data-route="insights">Explore patterns in your recorded days →</button></section>`;}
function companion(){return `${header('A space to talk.','Talk freely. Review any suggested journal entry before saving.')}${selectedRecord?`<div class="context-chip"><div><strong>Asking about: ${esc(state.records.find(r=>r.id===selectedRecord)?.title||'Unavailable record')}</strong><p>Only this report is used for this question. Earlier chat and your journal are excluded.</p></div>${button('Clear report','clear-context')}</div>`:''}${receipt()}<div class="companion-layout"><section class="chat-panel"><div class="chat-top"><div class="companion-avatar">${icon('leaf')}</div><div><strong>Stillwell companion</strong><span>${mode()==='live'?'Live AI · source-linked context':'Prepared demo · scripted responses'}</span></div><span class="status-dot"></span></div><div class="messages" id="messages"><div class="message assistant"><p>Hi Maya. You’ve been keeping track of how your days feel. How are things today?</p><p>We can talk it through, look back at your journal, or get ready for your next appointment.</p></div>${state.messages.map(m=>`<div class="message ${m.role}">${esc(m.text).replace(/\n/g,'<br>')}${m.citations?.length?`<div class="answer-sources">${m.citations.map((c,j)=>`<button data-citation="${state.messages.indexOf(m)}:${j}">${icon('records')}${esc(c.title)}</button>`).join('')}</div>`:''}${m.trace?`<button class="text-btn answer-trace" data-trace="${state.messages.indexOf(m)}">How this answer was made</button>`:''}</div>`).join('')}${state.pending?`<div class="capture-card"><div class="capture-title">${icon('spark')} Ready to add to your journal</div><h4>${esc(state.pending.symptom)}</h4><div class="capture-details"><span>${date(state.pending.date)}</span><span>Intensity ${state.pending.severity??'not supplied'}</span><span>${state.pending.sleep?state.pending.sleep+'h sleep':'Sleep not supplied'}</span></div><p>${esc(state.pending.note)}</p><div class="actions">${button('Review & save','review-capture','primary','check')}${button('Dismiss','dismiss')}</div></div>`:''}</div>${chatError?`<div class="notice" role="alert">${esc(chatError.message)} ${button('Retry message','retry-chat')}</div>`:''}${aiBusy?'<div class="ai-progress" role="status"><span></span>Reading your selected context…</div>':''}${selectedRecord?'':`<div class="suggestions"><button data-prompt="Yesterday I had a headache, 3/5, and slept 6 hours.">Log how I’m feeling</button><button data-prompt="What patterns are in my journal?">Explore my patterns</button><button data-prompt="Help me prepare for my appointment.">Prepare for my visit</button></div>`}<form id="chat-form" class="chat-input"><span class="sr-only">Nothing is saved to your journal without your review.</span><textarea name="message" rows="2" aria-label="Message companion" placeholder="Tell me what’s on your mind…" required>${esc(draft)}</textarea><button class="send-btn" type="submit" aria-label="Send message" ${aiBusy?'disabled':''}>↑</button></form><p class="chat-footnote">${mode()==='live'?'Live AI uses the information you submit to this demo. Review its answers and extracted details.':'Prepared responses use this sample profile. Enable live AI on the server deployment.'}</p></section><aside class="context-rail">${selectedRecord?`<div class="context-block"><h3>This report only</h3><p>Your question uses the selected report. Clear the report to return to a general conversation.</p><button class="text-btn" data-record="${selectedRecord}">View selected report →</button></div>`:contextRail()}</aside></div>`;}
function contextRail(){return `<h3>The context behind our conversation</h3><p>You can inspect and change any of this.</p><div class="context-block"><span class="context-icon">${icon('track')}</span><h4>Your everyday</h4><p>${stats(state).entries} journal entries<br>Headaches, sleep and daily notes</p><button class="text-btn" data-route="tracking">View journal ${icon('arrow')}</button></div><div class="context-block"><span class="context-icon">${icon('records')}</span><h4>Your health history</h4><p>${state.records.length} records available<br>Saved text stays available; uploaded files last for this session.</p><button class="text-btn" data-route="records">View records ${icon('arrow')}</button></div><div class="context-block"><span class="context-icon">${icon('visit')}</span><h4>What’s next</h4><p>Primary care follow-up<br>18 September, 10:30am</p><button class="text-btn" data-route="visits">Your questions ${icon('arrow')}</button></div>`;}
function records(){let rs=state.records.filter(r=>(activeTab==='All records'||r.type===activeTab)&&JSON.stringify(r).toLowerCase().includes(filter.toLowerCase()));return `${header('Your history, brought together.','Original records, useful details and the full picture.',button('Add a record','upload','primary','plus'))}<div class="records-summary"><div><span class="file-icon">${icon('records')}</span><div><strong>${state.records.length} records</strong><p>Organised in your personal health history</p></div></div><div>${miniTag('Sample profile','mint')}<span class="quiet">Last reviewed today</span></div></div><div class="toolbar"><div class="tabs">${['All records','Visit note','Lab report','Extracted record','Personal note'].map(t=>`<button class="${activeTab===t?'selected':''}" data-tab="${t}">${t}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="record-search" placeholder="Search your records" value="${esc(filter)}" aria-label="Search records"></label></div><div class="record-list">${rs.length?rs.map(r=>`<button class="record-full" data-record="${r.id}"><span class="file-icon ${r.type==='Lab report'?'sand':''}">${icon(r.type==='Lab report'?'insights':'records')}</span><span class="record-info"><small>${r.date?date(r.date)+' '+r.date.slice(0,4):'Date not supplied'}</small><h3>${esc(r.title)}</h3><p>${esc(r.provider)}</p></span><span class="tag">${esc(r.type)}</span><span class="record-source">${r.extraction?'Reviewed extraction':'Original available'} ${icon('arrow')}</span></button>`).join(''):'<div class="empty">No matching records. Try another search or add a note.</div>'}</div><div class="record-bottom"><div><h3>A record is a starting point.</h3><p>Ask about a document, check the original, or bring it to your next visit.</p>${button('Ask my companion','talk','secondary','chat')}</div><div class="paper-stack" aria-hidden="true">${icon('records')}</div></div>`;}
function tracking(){return `${header('The everyday matters.','Small observations, all in one place.',button('Log an observation','log','primary','plus'))}<div class="tracking-layout"><section class="panel"><div class="panel-heading"><h3>Your journal</h3>${miniTag('September 2026')}</div><div class="calendar-strip">${Array.from({length:13},(_,i)=>{let day=i+1;let has=state.observations.some(o=>+o.date.slice(-2)===day);return `<span class="${has?'logged':''} ${day===13?'today':''}"><small>${['M','T','W','T','F','S','S'][i%7]}</small>${day}<i></i></span>`;}).join('')}</div>${journalRows()}</section><aside><section class="panel"><div class="panel-heading"><h3>Your reminders</h3>${icon('clock')}</div><p class="subtle">In-app schedule preview</p>${state.reminders.map(r=>`<div class="reminder"><div><strong>${esc(r.text)}</strong><p>${r.time} · daily</p></div><button class="toggle ${r.active?'on':''}" data-reminder="${r.id}" role="switch" aria-checked="${r.active}" aria-label="${esc(r.text)}"></button></div>`).join('')}${button('Add a reminder','reminder','secondary','plus')}</section><section class="panel med-panel"><h3>Medication notes</h3><p>Keep a record of what you reported taking. This does not change your prescribed plan.</p>${state.medications.filter(m=>m.name!=='Medication list').map(m=>`<div class="med-item"><strong>${esc(m.name)}</strong><p>${esc(m.detail)}</p>${miniTag('Patient reported')}</div>`).join('')}${button('Add medication note','med','secondary','plus')}</section><p class="aside-caption">No entry doesn’t mean no symptoms.<br>Unlogged days stay unknown.</p></aside></div>`;}
function insights(){let groups=comparison(state),s=stats(state);return `${header('See your days in context.','Explore what changes together. Bring useful questions to your clinician.',button('Add to visit questions','insight-question','secondary','plus'))}<section class="panel insight-hero"><div class="panel-heading"><div><h3>Headaches & sleep</h3><p>Two parts of your daily story, side by side</p></div>${miniTag('1–13 Sep 2026')}</div><div class="legend"><span><i class="green"></i>Headache intensity · /5</span><span><i class="gold"></i>Sleep · hours, separate scale</span></div>${chart(true)}<div class="insight-footer"><span>${s.days} days recorded</span><span>Self-reported sample data</span><button class="text-btn" data-route="tracking">Inspect observations ${icon('arrow')}</button></div></section><div class="insight-grid"><section class="panel"><div class="panel-heading"><h3>A closer look at sleep</h3>${icon('insights')}</div><p>Average recorded headache intensity, grouped by reported sleep.</p>${groups.map(g=>`<div class="comparison-row"><div><span>${g.label}</span><strong>${g.average?.toFixed(1)??'—'}<small> / 5</small></strong></div><div class="bar-track"><i style="width:${(g.average??0)*20}%"></i></div><small>${g.count} paired observations</small></div>`).join('')}<div class="notice">This is an observation in a small sample, not proof that sleep caused a headache.</div></section><section class="panel question-panel"><div class="round-icon">${icon('chat')}</div><h3>A useful conversation<br>starts with a question.</h3><p>“Could we look at my sleep and headache journal together at my next visit?”</p>${button('Save this question','insight-question','primary','plus')}<button class="text-btn" data-route="companion">Explore with my companion ${icon('arrow')}</button></section></div>`;}
function visits(){const prep=state.visitPrep||{};return `${header('What matters for your next visit?','Gather your priorities and the information you want to bring. No upload required.')}<div class="visit-banner"><div class="date-tile"><strong>18</strong><span>Sep</span></div><div><h3>Primary care follow-up</h3><p>Friday, 10:30am · Fictional sample clinic, Singapore</p></div></div><div class="visit-layout"><section><section class="panel"><span class="step-label">1. Your priorities</span><h3>Start with what’s on your mind</h3><label for="visit-concern">What would you like help with?<textarea id="visit-concern" rows="3" placeholder="For example: I want to discuss how my headaches affect my day.">${esc(prep.concern||'')}</textarea></label><p class="subtle" id="concern-status">Saved in this browser as you type.</p><div class="panel-heading"><h3>Your questions</h3>${button('Add question','question','secondary','plus')}</div><p class="subtle">Move the most important question to the top.</p>${state.questions.length?state.questions.map((q,i)=>`<div class="question-row"><span class="question-number">${i+1}</span><p>${esc(q.text)}</p><button class="icon-btn" data-up="${q.id}" ${i?'':'disabled'} aria-label="Move question ${i+1} up">↑</button><button class="icon-btn" data-remove-q="${q.id}" aria-label="Remove question ${i+1}">${icon('close')}</button></div>`).join(''):'<p>No questions yet. You can start with just your concern.</p>'}</section><section class="panel evidence-panel"><span class="step-label">2. Supporting information</span><h3>Choose what to bring</h3><p>You decide what appears in the brief. Uncheck anything you don’t want to include.</p><details open><summary>Records · ${state.records.length} available</summary>${state.records.map(r=>`<label class="evidence-choice"><input type="checkbox" data-evidence="recordIds" value="${r.id}" ${prep.recordIds==null||prep.recordIds.includes(r.id)?'checked':''}><span><strong>${esc(r.title)}</strong><small>${date(r.date)}</small></span><button type="button" class="text-btn" data-record="${r.id}">View</button></label>`).join('')||'<p>No records. You can still prepare your brief.</p>'}</details><details><summary>Journal · ${state.observations.length} entries available</summary>${state.observations.map(o=>`<label class="evidence-choice"><input type="checkbox" data-evidence="observationIds" value="${o.id}" ${prep.observationIds==null||prep.observationIds.includes(o.id)?'checked':''}><span><strong>${esc(o.symptom)} · ${date(o.date)}</strong><small>${esc(o.note)}</small></span></label>`).join('')||'<p>No journal entries to include.</p>'}</details></section></section><aside class="brief-paper"><span class="step-label">3. Review & bring along</span><h3>Your appointment brief</h3><p class="subtle">Preview reflects your current choices.</p><pre id="visit-preview" class="visit-preview">${esc(brief(state))}</pre><div class="actions">${button('Preview & print PDF','print','primary','download')}${button('Download text','export-brief','secondary')}</div></aside></div>`;}
function family(){return `${header('Your health. Your circle.','Support from the people you choose, on your terms.')}<div class="family-disclosure">${icon('shield')} Sharing is a local interface simulation. No invitations or health data are sent.</div><div class="family-layout"><section><div class="panel member-panel"><div class="member-head"><span class="avatar large peach">ET</span><div><h3>Emma Tan</h3><p>Sister · sample caregiver</p></div>${miniTag(state.family.active?'Access enabled':'Access revoked',state.family.active?'mint':'')}</div><hr><h4>Choose what Emma can see</h4><p class="subtle">Preview the information you would share.</p>${[['journal','Daily journal','Symptoms, sleep and everyday notes'],['visits','Appointment briefs','Your priorities and visit preparation'],['records','Health records','Documents and their original contents']].map(([key,label,sub])=>`<div class="permission-row"><div><strong>${label}</strong><p>${sub}</p></div><button class="toggle ${state.family[key]?'on':''}" data-permission="${key}" role="switch" aria-checked="${state.family[key]}" aria-label="Share ${label}" ${state.family.active?'':'disabled'}></button></div>`).join('')}<div class="member-actions">${button('Preview Emma’s view','preview-family','primary','family')}${button(state.family.active?'Revoke access':'Restore demo access','revoke','secondary')}</div></div><div class="small-note family-note">${icon('shield')}<div><strong>You choose what to share.</strong><p>This preview illustrates controls, not production security. Exported files cannot be recalled.</p></div></div></section><aside class="family-side"><div class="circle-illustration"><span class="avatar huge">MT</span><span class="avatar large peach">ET</span><i></i></div><h2>A little support<br>goes a long way.</h2><p>Bring someone you trust into the picture, without handing over your whole history.</p><div class="family-tip">${icon('check')} Select only what’s helpful.<br>${icon('check')} Change your choices any time.<br>${icon('check')} Keep your own voice at the centre.</div></aside></div>`;}
function render(){if(!routes.includes(route))route='overview';const section=sectionFor(route);const items=[['overview','leaf','Today','today'],['records','records','My health','health'],['visits','visit','My next visit','visit']];const labels={overview:'Today',companion:'Companion',records:'Records',tracking:'Journal',insights:'Patterns',visits:'My next visit',family:'Family preview'};$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-icon">${icon('leaf')}</span>stillwell<span class="brand-dot">°</span></a><div class="workspace-label">Your personal health space</div><nav aria-label="Main navigation">${items.map(([r,i,label,key])=>`<button data-route="${r}" class="nav-item ${section===key?'active':''}" ${section===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" data-route="family">${icon('family')} Family preview</button><div class="demo-note">Fictional profile · September 2026<p>This is a concept demo.</p><button data-action="about">What works in this demo?</button></div><button class="profile" data-action="profile"><span class="avatar">MT</span><span><strong>Maya Tan</strong><small>Demonstration profile</small></span></button></div></aside><main><header class="topbar"><div class="breadcrumb">${labels[route]}</div><div class="topbar-right"><button class="text-btn" data-action="talk">${icon('chat')} Companion</button><button class="ai-mode-button ${mode()}" data-action="ai-settings">${mode()==='live'?'Live AI':'Prepared demo'}</button><button class="icon-btn" data-action="profile" aria-label="Demo profile and settings"><span class="profile-initials">MT</span></button></div></header><div class="page">${section==='health'?`<nav class="health-tabs" aria-label="My health">${[['records','Records'],['tracking','Journal'],['insights','Patterns']].map(([r,l])=>`<button data-route="${r}" ${r===route?'aria-current="page"':''}>${l}</button>`).join('')}</nav>`:''}${({overview,companion,records,tracking,insights,visits,family}[route])()}</div><footer>Stillwell · A little clarity, every day.<button class="text-btn" data-route="family">Family preview</button><span>Fictional demo · ${mode()==='live'?'Live AI; review generated answers':'Prepared, scripted examples'}</span></footer></main>`;if(route==='companion')$('#messages').scrollTop=$('#messages').scrollHeight;if(route==='tracking'&&focusEntry){document.getElementById('entry-'+focusEntry)?.scrollIntoView({block:'center'});document.getElementById('entry-'+focusEntry)?.focus();}}
let modalOpener=null;
function modal(title,body){if(!$('#dialog').open)modalOpener=document.activeElement;$('#dialog').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;$('#dialog').showModal();}
function download(name,text,type='text/plain'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function observationForm(entry,id=''){modal(id?'Edit your observation':'Review your observation',`<form id="observation-form" data-id="${id}"><div class="form-grid"><label>Date<input type="date" name="date" value="${entry.date||'2026-09-13'}" min="2026-09-01" max="2026-09-13" required></label><label>Symptom<input name="symptom" value="${esc(entry.symptom||'Headache')}" required></label><label>Intensity (0–5, optional)<input name="severity" type="number" min="0" max="5" step="1" value="${entry.severity??''}"></label><label>Sleep (hours, optional)<input name="sleep" type="number" min="0" max="24" step="0.1" value="${entry.sleep??''}"></label></div><label>Your words<textarea name="note" rows="3">${esc(entry.note||'')}</textarea></label><p class="subtle">Only save what you reported. Blank values stay unknown.</p><div class="modal-actions">${id?`<button type="button" class="btn danger" data-delete="${id}">Delete observation</button>`:''}<button type="submit" class="btn primary">Save observation</button></div></form>`);}
function addQuestion(t){if(state.questions.some(q=>q.text===t)){toast('This question is already in your brief.');return;}state.questions.push({id:'q'+Date.now(),text:t});save();render();toast('Question added to your visit brief');}
const insightQuestion='Could we look at my sleep and headache journal together?';
function preparedSend(text){state.messages.push({role:'user',text});let entry=parseDemo(text);let response;if(/pattern|journal|compare/.test(text.toLowerCase())&&!entry){let g=comparison(state);response=`In this sample journal, average headache intensity is ${g[0].average?.toFixed(1)??'unavailable'}/5 across ${g[0].count} entries with under 7 hours of sleep, and ${g[1].average?.toFixed(1)??'unavailable'}/5 across ${g[1].count} entries with 7 hours or more. This is a small set of observations, not proof of a cause. You can inspect every entry in Patterns & insights.`;}else if(/appointment|visit/.test(text.toLowerCase())&&!entry){response=`Your follow-up is on 18 September. You have ${state.questions.length} questions saved. We can bring your recent journal and records together in a brief you can review under Appointments.`;}else if(entry){state.pending=entry;response='That sounds like a difficult part of your day. I’ve drafted a journal entry from what you shared. Please check the details before saving; anything you didn’t mention stays blank.';}else{response='This frontend demo can show journal capture, a comparison of your recorded sleep and headaches, or appointment preparation. It does not generate live medical answers. Try one of the suggested prompts below.';}state.messages.push({role:'assistant',text:response});draft='';save();render();}
document.addEventListener('click',e=>{let el=e.target.closest('button,a[data-route]');if(!el)return;let d=el.dataset;if(d.viewEntry){focusEntry=d.viewEntry;go('tracking');return;}if(d.askRecord){if(aiBusy){toast('Wait for your current reply before changing context.');return;}selectedRecord=d.askRecord;draft='Help me understand this report and what I could ask at my appointment.';chatError=null;$('#dialog').close();go('companion');return;}if(d.recordQuestion){const r=state.records.find(r=>r.id===d.recordQuestion);questionForm('Could we discuss my '+(r?.title||'report')+'?');return;}if(d.citation){showCitation(d.citation);return;}if(d.trace){showTrace(Number(d.trace));return;}if(d.original){const file=originalFiles.get(d.original);if(file)window.open(URL.createObjectURL(file),'_blank','noopener');return;}if(d.route){go(d.route);return;}if(d.tab){activeTab=d.tab;render();return;}if(d.prompt){send(d.prompt);return;}if(d.record){let r=state.records.find(r=>r.id===d.record);if(!r)return;modal(r.title,`<div class="source-meta">${miniTag(r.type)}<span>${date(r.date)} · ${esc(r.provider)}</span></div><pre class="source-document">${esc(r.body)}</pre><div class="notice">${r.extraction?'AI-extracted content, reviewed by you. Source quotes are model transcriptions, not independently verified.':'Original source preserved. This is demonstration content, not a clinical record.'}</div><div class="modal-actions">${r.extraction&&!originalFiles.has(r.id)?'<p class="subtle">The original file is no longer available in this session. Saved extracted text is shown above.</p>':''}${originalFiles.has(r.id)?`<button class="btn secondary" data-original="${r.id}">Open original file</button>`:''}<button class="btn primary" data-ask-record="${r.id}">Ask about this report</button><button class="btn secondary" data-record-question="${r.id}">Add a visit question</button></div>`);return;}if(d.edit){observationForm(state.observations.find(o=>o.id===d.edit),d.edit);return;}if(d.delete){state=removeObservation(state,d.delete);save();$('#dialog').close();render();toast('Observation removed from journal, charts and brief');return;}if(d.reminder){state.reminders.find(r=>r.id===d.reminder).active=!state.reminders.find(r=>r.id===d.reminder).active;save();render();return;}if(d.permission){state.family[d.permission]=!state.family[d.permission];save();render();return;}if(d.up){let i=state.questions.findIndex(q=>q.id===d.up);if(i>0)[state.questions[i-1],state.questions[i]]=[state.questions[i],state.questions[i-1]];save();render();return;}if(d.removeQ){state.questions=state.questions.filter(q=>q.id!==d.removeQ);save();render();return;}
const a=d.action;if(!a)return;if(a==='dismiss-intro'){ux.introDismissed=true;saveUx();render();return;}if(a==='clear-context'){if(aiBusy)return;selectedRecord=null;draft='';render();return;}if(a==='retry-chat'){if(chatError){selectedRecord=chatError.recordId;send(chatError.text,true);}return;}if(a==='retry-extraction'){if(retryFile)processLiveFile(retryFile);return;}if(a==='review-original'){if(liveExtraction)window.open(URL.createObjectURL(liveExtraction.file),'_blank','noopener');return;}
if(a==='ai-settings'){aiSettings();return;}if(a==='use-prepared'){if(aiBusy){toast('Wait for the current reply before changing mode.');return;}setMode('prepared');$('#dialog').close();render();return;}if(a==='close'){extractionAttempt++;$('#dialog').close();}
if(a==='talk'&&!aiBusy){selectedRecord=null;}if(a==='talk'||a==='visit'){$('#dialog').close();go(a==='talk'?'companion':'visits');}
if(a==='log')observationForm({});
if(a==='review-capture')observationForm(state.pending);
if(a==='dismiss'){state.pending=null;save();render();}
if(a==='insight-question')questionForm(insightQuestion);
if(a==='question')modal('What would you like to ask?',`<form id="question-form"><label>Your question<textarea name="question" rows="3" required></textarea></label><div class="modal-actions"><button class="btn primary" type="submit">Add to my brief</button></div></form>`);
if(a==='reminder')modal('Add a reminder',`<form id="reminder-form"><label>What would you like to remember?<input name="text" required placeholder="e.g. Evening journal"></label><label>Time<input name="time" type="time" value="20:00" required></label><p class="notice">This schedules an in-app preview. No push or email notification will be sent.</p><div class="modal-actions"><button class="btn primary" type="submit">Save reminder</button></div></form>`);
if(a==='med')modal('Add a medication note',`<form id="med-form"><label>Name<input name="name" required></label><label>What would you like to record?<textarea name="detail" required placeholder="Use information from your existing prescription or your own observation."></textarea></label><p class="notice">This demo does not recommend or change medication.</p><div class="modal-actions"><button class="btn primary" type="submit">Save note</button></div></form>`);
if(a==='upload'){extractionAttempt++;liveExtraction=null;}if(a==='upload')modal('Bring your records together',`<p>Add a note or walk through a sample document import.</p><div class="upload-zone">${icon('records')}<h3>Your records, in your own space</h3><p>${mode()==='live'?'Use a fictional PDF, PNG, JPEG or TXT file, up to 2 MB. Review extracted details before saving.':'Text notes import locally. Enable live AI for PDF/image extraction, or try the prepared sample.'}</p><input id="file-input" type="file" accept=".txt,.pdf,.png,.jpg,.jpeg" aria-label="Choose a record file"></div>${button('Try sample report extraction','sample-import','primary','spark')}`);
if(a==='sample-import'){startSample();return;}if(a==='legacy-sample-import')modal('Review sample extraction',`<p class="notice">Simulated extraction from a prepared fictional report. No AI document processing was performed.</p><form id="import-form"><label>Document title<input name="title" value="September follow-up note" required></label><label>Document date<input type="date" name="date" value="2026-09-13" required></label><label>Extracted note<textarea name="body" rows="4" required>Patient reports recurring headaches. Patient would like to discuss their sleep and symptom journal at the next visit. No treatment changes are documented.</textarea></label><div class="modal-actions"><button class="btn primary" type="submit">Confirm & add record</button></div></form>`);
if(a==='export-brief')download('stillwell-visit-brief.txt',brief(state));
if(a==='export-data')download('stillwell-demo-data.json',JSON.stringify(state,null,2),'application/json');
if(a==='print')modal('Your appointment brief',`<pre class="source-document printable-brief">${esc(brief(state))}</pre><div class="modal-actions">${button('Print / save PDF','print-now','primary','download')}</div>`);
if(a==='print-now')window.print();
if(a==='revoke'){state.family.active=!state.family.active;save();render();toast(state.family.active?'Demo access restored':'Access revoked in this local preview');}
if(a==='preview-family')modal('Emma’s view · local preview',state.family.active?`<p class="notice">Simulated caregiver view, not a signed-in account.</p>${state.family.journal?`<h3>Shared journal</h3>${journalRows(2,false)}`:''}${state.family.visits?`<h3>Shared appointment priorities</h3><ul>${state.questions.map(q=>`<li>${esc(q.text)}</li>`).join('')}</ul>`:''}${state.family.records?`<h3>Shared records</h3>${state.records.map(r=>`<p>${esc(r.title)}</p>`).join('')}`:''}${!state.family.journal&&!state.family.visits&&!state.family.records?'<p>No information has been selected for sharing.</p>':''}`:'<div class="empty">Access has been revoked. No health information is available in this preview.</div>');
if(a==='reset')modal('Reset the demonstration?',`<p>This restores Maya’s original synthetic profile and removes local edits, messages and imports.</p><div class="modal-actions">${button('Cancel','close')}${button('Reset demo','confirm-reset','primary')}</div>`);
if(a==='confirm-reset'){if(aiBusy){toast('Wait for the current response before resetting.');return;}extractionAttempt++;selectedRecord=null;draft='';chatError=null;originalFiles.clear();ux={};saveUx();state=seed();save();$('#dialog').close();go('overview');toast('Demo restored to its opening state');}
if(a==='profile')modal('Maya’s demonstration profile',`<p>This is an invented adult patient profile for the VIP@SoC product demonstration. Do not enter real patient information.</p><p>Saved demo data stays in this browser. In live mode, selected records and messages are sent through the server to OpenAI. No clinical service is connected.</p><div class="modal-actions">${button('Export demo data','export-data','secondary','download')}${button('Reset demo','reset')}</div>`);
if(a==='about')modal('What works in this demo?',`<p><strong>Working locally:</strong> navigation, journal capture and correction, charts calculated from entries, record review, text-note import, question ordering, exports and reset.</p><p><strong>Live on the configured server:</strong> OpenAI conversation, document extraction and source-linked answers. Prepared mode uses scripted responses. Reminders and family access remain simulations; no device or HealthHub integration.</p><p>The sample story is fictional. This prototype illustrates a product concept and does not provide medical advice.</p>`);
});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,v=new FormData(f);if(f.id==='ai-code-form'){if(aiBusy){toast('Wait for the current reply before changing mode.');return;}setCode(v.get('code').trim());setMode('live');$('#dialog').close();render();toast('Live mode selected. The server checks the code on your first request.');return;}if(f.id==='live-import-form'){saveLiveExtraction(v);return;}if(f.id==='chat-form'){let text=v.get('message').trim();if(text)send(text);return;}if(f.id==='observation-form'){let entry={date:v.get('date'),symptom:v.get('symptom'),severity:v.get('severity')===''?null:+v.get('severity'),sleep:v.get('sleep')===''?null:+v.get('sleep'),note:v.get('note'),source:f.dataset.id?state.observations.find(o=>o.id===f.dataset.id).source:state.pending?'Conversation':'Manual journal'};entry.id=f.dataset.id||'obs-'+crypto.randomUUID();state=f.dataset.id?editObservation(state,f.dataset.id,entry):addObservation(state,entry);ux.lastSaved={kind:'observation',id:entry.id,label:entry.symptom+' · '+date(entry.date)};saveUx();state.pending=null;toast('Saved. Your journal, insights and visit brief are updated.');}
if(f.id==='question-form'){const text=v.get('question').trim();if(!text)return;addQuestion(text);$('#dialog').close();modal('Question added to your brief',`<p>${esc(text)}</p><div class="modal-actions">${button('View my brief','visit','primary')}${button('Continue here','close')}</div>`);return;}
if(f.id==='reminder-form'){state.reminders.push({id:'rem'+Date.now(),text:v.get('text'),time:v.get('time'),active:true});toast('Reminder saved to the in-app preview');}
if(f.id==='med-form'){state.medications.push({name:v.get('name'),detail:v.get('detail'),reported:true});toast('Medication note saved');}
if(f.id==='import-form'){state.records.unshift({id:'r'+Date.now(),title:v.get('title'),date:v.get('date'),body:'SYNTHETIC SAMPLE — REVIEWED SIMULATED EXTRACTION\n'+v.get('body'),provider:'Sample document import',type:'Visit note'});toast('Reviewed record added to your history');}
save();$('#dialog').close();render();});
document.addEventListener('input',e=>{if(e.target.id==='visit-concern'){state.visitPrep={...state.visitPrep,concern:e.target.value};save();$('#visit-preview').textContent=brief(state);}if(e.target.matches('#chat-form textarea'))draft=e.target.value;if(e.target.id==='record-search'){let pos=e.target.selectionStart;filter=e.target.value;render();$('#record-search').focus();$('#record-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.dataset.evidence){const key=e.target.dataset.evidence;const ids=(key==='recordIds'?state.records:state.observations).map(x=>x.id);const selected=new Set(state.visitPrep?.[key]??ids);if(e.target.checked)selected.add(e.target.value);else selected.delete(e.target.value);state.visitPrep={...state.visitPrep,[key]:[...selected]};save();$('#visit-preview').textContent=brief(state);return;}if(e.target.id!=='file-input')return;let file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Choose a file smaller than 2 MB for this demo.');return;}if(mode()==='live'){await processLiveFile(file);return;}if(!file.name.toLowerCase().endsWith('.txt')){modal('File received · preview only',`<p>${esc(file.name)}</p><p class="notice">This frontend does not extract PDF or image contents. Use the sample extraction to demonstrate review, or import a .txt note to read its actual contents.</p>${button('Try sample extraction','sample-import','primary')}`);return;}let text=await file.text();liveExtraction={file,localText:true,result:{title:file.name,date:null,summary:text.slice(0,50000),fields:[],uncertainties:[],trace:{model:'Local text import'}}};reviewExtraction();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(route===next)return;route=next;render();$('.page-heading h1')?.focus({preventScroll:true});});
render();
discover().then(()=>render());

function aiSettings(){const status=getStatus();modal('Choose your demonstration mode',`<p><strong>${status.liveAvailable?'Live AI server is configured.':'Live AI is not configured on this host.'}</strong></p><p>Live mode sends selected synthetic records and messages to OpenAI through the server. The access code protects the demonstration; it is not an OpenAI API key.</p>${status.liveAvailable?`<form id="ai-code-form"><label>Demo access code<input name="code" type="password" autocomplete="off" required value="${esc(getCode())}"></label><div class="modal-actions"><button class="btn primary" type="submit">Enable live AI</button></div></form>`:'<div class="notice">Use the Render server with OPENAI_API_KEY and DEMO_ACCESS_CODE configured. Prepared mode remains available until the live server is configured.</div>'}<div class="modal-actions">${button('Use prepared mode','use-prepared')}</div>`);}
async function send(text,retry=false){if(aiBusy)return;if(state.pending){toast('Review and save, or dismiss your current journal draft first.');return;}if(selectedRecord&&!state.records.some(r=>r.id===selectedRecord)){toast('Choose an available report before asking.');return;}if(mode()!=='live'){chatError=null;if(retry&&state.messages.at(-1)?.role==='user'&&state.messages.at(-1)?.text===text)state.messages.pop();if(selectedRecord){state.messages.push({role:'user',text},{role:'assistant',text:'This is a prepared example. Open the saved report to inspect its text; enable live AI to ask new questions about this document.'});draft='';save();render();return;}preparedSend(text);return;}const requestRecord=selectedRecord;const payload=chatPayload(state,text,requestRecord);if(retry&&payload.history.at(-1)?.role==='user'&&payload.history.at(-1)?.text===text)payload.history.pop();aiBusy=true;chatError=null;if(!retry)state.messages.push({role:'user',text});if(!retry||draft===text)draft='';save();render();try{const answer=await api('chat',payload);state.messages.push({role:'assistant',text:answer.message,citations:answer.citations,trace:answer.trace});if(answer.observation)state.pending={...answer.observation,source:'Conversation'};save();}catch(error){chatError={text,recordId:requestRecord,message:'Message not completed. '+error.message};if(!draft)draft=text;}finally{aiBusy=false;render();}}
function currentSource(id,answerIndex){if(id==='message:current')return messageForAnswer(state.messages,answerIndex);if(id.startsWith('record:'))return state.records.find(r=>'record:'+r.id===id)?.body;if(id.startsWith('journal:')){let o=state.observations.find(o=>'journal:'+o.id===id);if(!o)return null;return JSON.stringify({id:o.id,date:o.date,symptom:o.symptom,severity:o.severity,sleep:o.sleep,note:o.note});}if(id==='calculation:sleep')return JSON.stringify({method:'Mean recorded headache intensity by reported sleep group; paired entries only, not causal inference',groups:comparison(state)});return null;}
function showCitation(key){const [i,j]=key.split(':').map(Number),c=state.messages[i]?.citations?.[j];if(!c)return;const source=currentSource(c.sourceId,i);const matches=source&&source.replace(/\s+/g,' ').includes(c.quote.replace(/\s+/g,' '));modal(c.title,`${matches?'':`<div class="notice">This source was changed or removed after the answer. The earlier quote is no longer supported by the current record. Ask again using the updated information.</div>`}<h4>Passage cited in the answer</h4><blockquote class="citation-quote">${esc(c.quote)}</blockquote><h4>Current source</h4><pre class="source-document">${source?esc(source):'Source removed.'}</pre><p class="subtle">A source match verifies attribution, not a clinical conclusion.</p>`);}
function showTrace(i){let t=state.messages[i]?.trace;if(!t)return;modal('How this answer was made',`<div class="trace-grid"><div><small>Response</small><strong>Live OpenAI request</strong></div><div><small>Model</small><strong>${esc(t.model)}</strong></div><div><small>Selected sources</small><strong>${t.sourcesConsidered}</strong></div><div><small>Response time</small><strong>${(t.durationMs/1000).toFixed(1)} seconds</strong></div></div><p>The server selected relevant records and recent journal entries, supplied deterministic calculations, then checked the returned citation IDs and quoted text.</p><p class="subtle">Context version: ${esc(t.contextHash)}${t.usage?` · ${t.usage.inputTokens} input tokens · ${t.usage.outputTokens} output tokens`:''}</p><p class="notice">Structured output and source checking do not guarantee medical accuracy.</p>`);}
async function processLiveFile(file){const attempt=++extractionAttempt;retryFile=file;liveExtraction=null;modal('Reading your document',`<div class="ai-progress" role="status"><span></span>Extracting ${esc(file.name)} with live AI…</div><p>Nothing is saved until you review the result.</p>`);try{const mime=file.type||(file.name.endsWith('.txt')?'text/plain':'application/pdf');const payload={name:file.name,mime};if(mime==='text/plain')payload.text=await file.text();else payload.data=await fileData(file);const result=await api('extract',payload);if(attempt!==extractionAttempt||!$('#dialog').open)return;liveExtraction={result,file};reviewExtraction();}catch(error){if(attempt!==extractionAttempt||!$('#dialog').open)return;modal('Document not saved',`<p role="alert">${esc(error.message)}</p><div class="modal-actions">${button('Retry this file','retry-extraction','primary')}${button('Choose another file','upload')}</div>`);}}
function saveLiveExtraction(values){if(!liveExtraction)return;const id='r'+crypto.randomUUID(),r=liveExtraction.result;const fields=r.fields.map((f,i)=>({...f,value:values.get('value-'+i),unit:values.get('unit-'+i)}));const body=values.get('summary')+'\n\n'+fields.map(f=>`${f.label}: ${f.value} ${f.unit||''}\nOriginal extracted quote: ${f.quote}${f.page?' (page '+f.page+')':''}`).join('\n\n');state.records.unshift({id,title:values.get('title'),date:values.get('date')||'',provider:liveExtraction.localText?'Imported text · reviewed':liveExtraction.prepared?'Prepared sample · reviewed':'AI extraction · user reviewed',type:'Extracted record',body,extraction:{model:r.trace.model,originalName:liveExtraction.file.name,fields,dateKnown:!!values.get('date')}});originalFiles.set(id,liveExtraction.file);ux.lastSaved={kind:'record',id,label:values.get('title')};saveUx();liveExtraction=null;save();$('#dialog').close();go('records');modal('Your record is saved',`<p>${esc(values.get('title'))} is now in My health.</p><div class="modal-actions"><button class="btn primary" data-ask-record="${id}">Ask about this report</button><button class="btn secondary" data-record="${id}">View saved record</button></div>`);}

function receipt(){const l=ux.lastSaved;if(!l||l.kind!=='observation'||!state.observations.some(o=>o.id===l.id))return '';return `<div class="saved-receipt" role="status"><div><strong>Saved to your journal</strong><p>${esc(l.label)}</p></div><button class="btn secondary" data-view-entry="${l.id}">View saved entry →</button></div>`;}
function questionForm(text=''){modal('What would you like to ask?',`<form id="question-form"><label>Your question<textarea name="question" rows="3" required>${esc(text)}</textarea></label><div class="modal-actions"><button class="btn primary" type="submit">Add to my brief</button></div></form>`);}
function startSample(){const file=new File([sampleText],'stillwell-sample-report.txt',{type:'text/plain'});if(mode()==='live'){processLiveFile(file);return;}liveExtraction={file,prepared:true,result:{title:'September sample screening',date:'2026-09-13',summary:'A fictional haemoglobin result for demonstration.',fields:[{label:'Haemoglobin',value:'12.8',unit:'g/dL',page:null,quote:'Haemoglobin: 12.8 g/dL'},{label:'Laboratory reference range',value:'12.0–15.5',unit:'g/dL',page:null,quote:'Laboratory reference range: 12.0–15.5 g/dL'}],uncertainties:[],trace:{model:'Prepared example'}}};reviewExtraction();}
function reviewExtraction(){const {result:r,prepared,localText}=liveExtraction;modal('Check your report details',`<p class="notice">${localText?'Local text import: no AI processing was performed. Review the text before saving.':prepared?'Prepared sample: no live AI extraction was performed.':'AI extracted these details. Check them against your document before saving.'}</p>${button('Open original document','review-original')}<form id="live-import-form"><label>Title<input name="title" required value="${esc(r.title)}"></label><label>Document date (optional)<input name="date" type="date" value="${esc(r.date||'')}"></label><label>Summary<textarea name="summary" rows="3" required>${esc(r.summary)}</textarea></label><h3>Extracted details</h3>${r.fields.map((f,i)=>`<fieldset class="extracted-field"><legend>${esc(f.label)}</legend><div class="form-grid"><label>Value<input name="value-${i}" value="${esc(f.value)}"></label><label>Unit<input name="unit-${i}" value="${esc(f.unit||'')}"></label></div><p class="source-label">Original extracted quote${f.page?' · page '+f.page:''}</p><blockquote>${esc(f.quote)}</blockquote></fieldset>`).join('')}${r.uncertainties.length?`<div class="notice">${r.uncertainties.map(esc).join('<br>')}</div>`:''}<p class="subtle">Corrections change your saved values, not the original extracted quotes. The original file is available only during this browser session; saved text stays in this browser.</p><div class="modal-actions"><button class="btn primary" type="submit">Confirm & save record</button>${button('Cancel','close')}</div></form>`);}
document.querySelector('#dialog').addEventListener('cancel',()=>{extractionAttempt++;});

document.querySelector('#dialog').addEventListener('close',()=>{if(modalOpener?.isConnected)modalOpener.focus();});
